import React, { Component } from 'react';
import './googlemap.css';

class Map extends Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedTime: '',
            petLocations: [],
            playing: false,
            currentPointIndex: 0,
            intervalId: null,
            currentPhoto: null,
        };
        this.map = null;
    }

    componentDidMount() {
        this.loadScript();
    }

    componentWillUnmount() {
        const script = document.getElementById('googleMaps');
        if (script) {
            document.head.removeChild(script);
        }
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
        }
    }

    loadScript = () => {
        const existingScript = document.getElementById('googleMaps');
        if (!existingScript) {
            const script = document.createElement('script');
            script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&libraries=places&callback=initMap`;
            script.id = 'googleMaps';
            script.async = true;
            script.defer = true;
            script.onload = this.initMap;
            document.head.appendChild(script);
        } else {
            this.initMap();
        }
    };

    initMap = () => {
        if (window.google && window.google.maps) {
            this.map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: { lat: 32.074572, lng: 34.797105 },
            });
            console.log('Google Maps API loaded successfully.');
        } else {
            console.error("Google Maps API failed to load.");
        }
    };

    fetchData = () => {
        fetch('http://localhost:3001/trackipetmap', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ pet_id: 1 }),
        })
            .then((response) => response.json())
            .then((data) => {
                const { lat, lng } = data;
                this.map.setCenter({ lat, lng });
                new window.google.maps.Marker({
                    position: { lat, lng },
                    map: this.map,
                    title: 'Pet Location',
                });
            })
            .catch((error) => console.error('Error fetching location:', error));
    };

    handleTimeChange = (event) => {
        this.setState({ selectedTime: event.target.value });
    };

    showHistory = () => {
        const { selectedTime } = this.state;
        if (!selectedTime) {
            alert('Please select a time period.');
            return;
        }

        fetch(`http://localhost:3001/locationhistory?pet_id=1&time=${selectedTime}`)
            .then((response) => response.json())
            .then((data) => {
                this.setState({ petLocations: data, currentPointIndex: 0, currentPhoto: null }, this.playHistory);
            })
            .catch((error) => console.error('Error fetching location history:', error));
    };

    playHistory = () => {
        const intervalId = setInterval(() => {
            const { currentPointIndex, petLocations } = this.state;
            if (currentPointIndex >= petLocations.length) {
                clearInterval(this.state.intervalId);
                this.setState({ playing: false });
                return;
            }

            const point = petLocations[currentPointIndex];
            this.addMarkerAndLine(point);

            this.setState({ currentPointIndex: currentPointIndex + 1 });
        }, 1000);

        this.setState({ intervalId, playing: true });
    };

    stopHistory = () => {
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
            this.setState({ playing: false });
        }
    };

    addMarkerAndLine = (point) => {
        const marker = new window.google.maps.Marker({
            position: { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
            map: this.map,
            title: `Pet Location at ${point.timestamp}`,
        });

        if (this.state.currentPointIndex > 0) {
            const previousPoint = this.state.petLocations[this.state.currentPointIndex - 1];
            const line = new window.google.maps.Polyline({
                path: [
                    { lat: parseFloat(previousPoint.latitude), lng: parseFloat(previousPoint.longitude) },
                    { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
                ],
                geodesic: true,
                strokeColor: '#FF0000',
                strokeOpacity: 1.0,
                strokeWeight: 2,
            });
            line.setMap(this.map);
        }

        // Fetch place details using Google Places API
        const service = new window.google.maps.places.PlacesService(this.map);
        const request = {
            location: new window.google.maps.LatLng(point.latitude, point.longitude),
            radius: '50'
        };

        service.nearbySearch(request, (results, status) => {
            if (status === window.google.maps.places.PlacesServiceStatus.OK) {
                console.log('Nearby search results:', results);
                const photoUrl = results[0].photos ? results[0].photos[0].getUrl({ maxWidth: 100, maxHeight: 100 }) : '';
                this.setState({
                    currentPhoto: {
                        name: results[0].name,
                        lat: point.latitude,
                        lng: point.longitude,
                        photoUrl: photoUrl
                    }
                });
            } else {
                console.error('Nearby search failed:', status);
            }
        });
    };

    render() {
        return (
            <div className="app-container">
                <div className="content-container-2">
                    <div className="sidebar">
                        <img src="../media/dog-location.png" alt="Dog Location" className="photo" />
                        <div className="dog-info">
                            <p className="info-text">Name: Bella</p>
                            <p className="info-text">Location: Tel Aviv</p>
                            <p className="info-text">Longitude: 32.074572</p>
                            <p className="info-text">Latitude: 34.797105</p>
                        </div>
                        <select onChange={this.handleTimeChange} value={this.state.selectedTime}>
                            <option value="">Select Time Period</option>
                            {Array.from({ length: 24 }, (_, i) => (
                                <option key={i + 1} value={`last ${i + 1} hours`}>{`Last ${i + 1} hours`}</option>
                            ))}
                            <option value="last day">Last Day</option>
                            <option value="last week">Last Week</option>
                        </select>
                        <button onClick={this.showHistory}>Show History</button>
                        <button onClick={this.fetchData}>Pet's Location</button>
                        <button onClick={this.playHistory} disabled={this.state.playing}>Play</button>
                        <button onClick={this.stopHistory} disabled={!this.state.playing}>Stop</button>
                    </div>
                    <div id="map"></div>
                    {this.state.currentPhoto && (
                        <div className="map-photo-container">
                            <img src={this.state.currentPhoto.photoUrl} alt={this.state.currentPhoto.name} className="small-photo" />
                            <h3>{this.state.currentPhoto.name}</h3>
                            <p>Latitude: {this.state.currentPhoto.lat}</p>
                            <p>Longitude: {this.state.currentPhoto.lng}</p>
                        </div>
                    )}
                </div>
            </div>
        );
    }
}

export default Map;
